import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useTier } from '../config/TierContext';
import { Tier } from '../config/tiers';

const SIDEBAR_WIDTH = 260;

const analyticsNav = [
  { path: '/', label: 'Travel Overview', aiOnly: false, icon: (
    <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
      <rect x="1" y="1" width="7" height="7" rx="1.5" stroke="currentColor" strokeWidth="1.5"/>
      <rect x="10" y="1" width="7" height="7" rx="1.5" stroke="currentColor" strokeWidth="1.5"/>
      <rect x="1" y="10" width="7" height="7" rx="1.5" stroke="currentColor" strokeWidth="1.5"/>
      <rect x="10" y="10" width="7" height="7" rx="1.5" stroke="currentColor" strokeWidth="1.5"/>
    </svg>
  )},
  { path: '/dashboard', label: 'Analytics Dashboard', aiOnly: false, icon: (
    <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
      <rect x="2" y="9" width="3.5" height="7" rx="1" stroke="currentColor" strokeWidth="1.5"/>
      <rect x="7.25" y="5" width="3.5" height="11" rx="1" stroke="currentColor" strokeWidth="1.5"/>
      <rect x="12.5" y="2" width="3.5" height="14" rx="1" stroke="currentColor" strokeWidth="1.5"/>
    </svg>
  )},
  { path: '/spotter', label: 'JETT AI', aiOnly: true, icon: (
    <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
      <circle cx="9" cy="9" r="7" stroke="currentColor" strokeWidth="1.5"/>
      <circle cx="9" cy="9" r="3" fill="currentColor"/>
    </svg>
  )},
  { path: '/reports', label: 'Reports', aiOnly: false, icon: (
    <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
      <rect x="3" y="1" width="12" height="16" rx="2" stroke="currentColor" strokeWidth="1.5"/>
      <line x1="6" y1="5.5" x2="12" y2="5.5" stroke="currentColor" strokeWidth="1.5"/>
      <line x1="6" y1="9" x2="12" y2="9" stroke="currentColor" strokeWidth="1.5"/>
      <line x1="6" y1="12.5" x2="10" y2="12.5" stroke="currentColor" strokeWidth="1.5"/>
    </svg>
  )},
];

const settingsNav = [
  { path: '/settings', label: 'Settings', icon: (
    <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
      <circle cx="9" cy="9" r="3" stroke="currentColor" strokeWidth="1.5"/>
      <path d="M9 1.5v2M9 14.5v2M1.5 9h2M14.5 9h2M3.4 3.4l1.4 1.4M13.2 13.2l1.4 1.4M3.4 14.6l1.4-1.4M13.2 4.8l1.4-1.4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/>
    </svg>
  )},
];

const TIERS: Tier[] = ['Starter', 'Essentials', 'Pro'];

export default function Sidebar() {
  const location = useLocation();
  const { tier, setTier, spotterEnabled } = useTier();

  const linkStyle = (path: string): React.CSSProperties => {
    const active = location.pathname === path;
    return {
      display: 'flex',
      alignItems: 'center',
      gap: 12,
      textDecoration: 'none',
      fontSize: 14,
      fontWeight: active ? 600 : 400,
      color: active ? '#ffffff' : 'rgba(255,255,255,0.55)',
      padding: '11px 16px',
      borderRadius: 8,
      backgroundColor: active ? '#7C3AED' : 'transparent',
      transition: 'all 0.15s ease',
      marginBottom: 2,
    };
  };

  const lockedLinkStyle = (path: string): React.CSSProperties => ({
    ...linkStyle(path),
    opacity: 0.45,
    cursor: 'default',
  });

  return (
    <aside
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        bottom: 0,
        width: SIDEBAR_WIDTH,
        backgroundColor: '#130829',
        display: 'flex',
        flexDirection: 'column',
        zIndex: 100,
      }}
    >
      {/* Logo */}
      <div style={{ padding: '1.5rem 1.25rem 0.75rem' }}>
        <div style={{ lineHeight: 1.1 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 4 }}>
            <span style={{ color: 'rgba(255,255,255,0.4)', fontSize: 10, fontWeight: 500, letterSpacing: '1px', textTransform: 'uppercase' }}>
              Powered by
            </span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <span style={{ color: '#ffffff', fontWeight: 800, fontSize: 26, letterSpacing: '-0.5px' }}>
              JETT
            </span>
            <span
              style={{
                backgroundColor: '#7C3AED',
                color: '#fff',
                fontSize: 9,
                fontWeight: 700,
                letterSpacing: '1.2px',
                textTransform: 'uppercase',
                padding: '3px 8px',
                borderRadius: 4,
              }}
            >
              ANALYTICS
            </span>
          </div>
        </div>
      </div>

      {/* Subscription Tier */}
      <div style={{ padding: '1rem 1.25rem 0.5rem' }}>
        <div style={{ color: 'rgba(255,255,255,0.35)', fontSize: 10, fontWeight: 600, letterSpacing: '1.5px', textTransform: 'uppercase', marginBottom: 10 }}>
          Subscription Tier
        </div>
        <div style={{ display: 'flex', gap: 0, backgroundColor: 'rgba(255,255,255,0.06)', borderRadius: 8, padding: 3 }}>
          {TIERS.map((t) => (
            <div
              key={t}
              onClick={() => setTier(t)}
              style={{
                flex: 1,
                textAlign: 'center',
                padding: '6px 0',
                fontSize: 12,
                fontWeight: t === tier ? 600 : 400,
                color: t === tier ? '#fff' : 'rgba(255,255,255,0.5)',
                backgroundColor: t === tier ? '#7C3AED' : 'transparent',
                borderRadius: 6,
                cursor: 'pointer',
                transition: 'all 0.15s ease',
              }}
            >
              {t}
            </div>
          ))}
        </div>
      </div>

      {/* Analytics section */}
      <div style={{ padding: '1.25rem 1.25rem 0' }}>
        <div style={{ color: 'rgba(255,255,255,0.35)', fontSize: 10, fontWeight: 600, letterSpacing: '1.5px', textTransform: 'uppercase', marginBottom: 10 }}>
          Analytics
        </div>
      </div>
      <nav style={{ padding: '0 0.75rem', display: 'flex', flexDirection: 'column', flex: 1 }}>
        {analyticsNav.map((item) => {
          const locked = item.aiOnly && !spotterEnabled;
          if (locked) {
            return (
              <Link key={item.path} to={item.path} style={lockedLinkStyle(item.path)}>
                <span style={{ display: 'flex', alignItems: 'center', width: 20, justifyContent: 'center' }}>{item.icon}</span>
                <span style={{ flex: 1 }}>{item.label}</span>
                <span style={{
                  fontSize: 9,
                  fontWeight: 700,
                  backgroundColor: 'rgba(255,255,255,0.12)',
                  color: 'rgba(255,255,255,0.5)',
                  padding: '2px 6px',
                  borderRadius: 4,
                  letterSpacing: '0.5px',
                  textTransform: 'uppercase',
                }}>PRO</span>
              </Link>
            );
          }
          return (
            <Link key={item.path} to={item.path} style={linkStyle(item.path)}>
              <span style={{ display: 'flex', alignItems: 'center', width: 20, justifyContent: 'center' }}>{item.icon}</span>
              {item.label}
            </Link>
          );
        })}

        <div style={{ flex: 1 }} />

        {settingsNav.map((item) => (
          <Link key={item.path} to={item.path} style={linkStyle(item.path)}>
            <span style={{ display: 'flex', alignItems: 'center', width: 20, justifyContent: 'center' }}>{item.icon}</span>
            {item.label}
          </Link>
        ))}
      </nav>

      {/* User profile */}
      <div
        style={{
          padding: '1rem 1.25rem',
          borderTop: '1px solid rgba(255,255,255,0.08)',
          display: 'flex',
          alignItems: 'center',
          gap: 10,
        }}
      >
        <div
          style={{
            width: 36,
            height: 36,
            backgroundColor: '#7C3AED',
            borderRadius: '50%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            flexShrink: 0,
          }}
        >
          <span style={{ color: '#fff', fontWeight: 700, fontSize: 13 }}>JT</span>
        </div>
        <div style={{ lineHeight: 1.3 }}>
          <div style={{ color: '#ffffff', fontWeight: 600, fontSize: 13 }}>JETT Analytics</div>
          <div style={{ color: 'rgba(255,255,255,0.4)', fontSize: 11 }}>{tier} Tier</div>
        </div>
      </div>
    </aside>
  );
}

export { SIDEBAR_WIDTH };
